'use client'
import { cn, useId, useSignal, useSignals } from '@cascivo/core'
import { builtin, currentLocale, t } from '@cascivo/i18n'
import { useRef } from 'react'
import type { ChangeEvent, DragEvent } from 'react'
import { Spinner } from '../spinner/spinner'
import styles from './file-uploader.module.css'

export interface UploaderFile {
  id: string
  name: string
  size?: number
  status: 'uploading' | 'complete' | 'error'
  errorMessage?: string
}

export interface FileUploaderLabels {
  label?: string
  drop?: string
  remove?: string
  uploading?: string
  complete?: string
  error?: string
}

export interface FileUploaderProps {
  /**
   * Controlled file list
   *
   * @defaultValue `[]`
   * @see the component manifest
   */
  files?: UploaderFile[]
  onFilesAdded?: (files: File[]) => void
  onRemove?: (id: string) => void
  /**
   * Allow multiple files
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  multiple?: boolean
  accept?: string
  maxSize?: number
  onRejected?: (files: File[], reason: 'size' | 'type') => void
  label?: string
  /**
   * Invisible accessible name, for when a visible element outside this component already
   * labels it and `label` would render that text a second time.
   *
   * `label` on this component is **visible**. `IconButton.label` and `Sparkline.label` are
   * invisible names, so an adopter arriving with that prior writes `label` here and gets the
   * text twice (2026-08-22 report item 13). Both props are listed side by side, each saying
   * which it is.
   */
  ariaLabel?: string
  hint?: string
  labels?: FileUploaderLabels
  /**
   * Disables the upload zone
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  disabled?: boolean
  className?: string
}

function matchesAccept(file: File, accept: string): boolean {
  const patterns = accept
    .split(',')
    .map((pattern) => pattern.trim())
    .filter(Boolean)
  if (patterns.length === 0) return true
  return patterns.some((pattern) => {
    if (pattern.startsWith('.')) {
      return file.name.toLowerCase().endsWith(pattern.toLowerCase())
    }
    if (pattern.endsWith('/*')) {
      return file.type.startsWith(pattern.slice(0, -1))
    }
    return file.type === pattern
  })
}

/**
 * Byte size in the reader's locale. The unit strings and the decimal separator were both
 * hardcoded English before ("1.5 MB" reads wrong in every comma-decimal locale), which the
 * component checklist forbids. `Intl.NumberFormat`'s `unit` style supplies both.
 */
function formatSize(bytes: number, locale: string): string {
  const [value, unit] =
    bytes >= 1024 * 1024
      ? [bytes / (1024 * 1024), 'megabyte' as const]
      : bytes >= 1024
        ? [bytes / 1024, 'kilobyte' as const]
        : [bytes, 'byte' as const]
  try {
    return new Intl.NumberFormat(locale, {
      style: 'unit',
      unit,
      unitDisplay: 'short',
      maximumFractionDigits: unit === 'byte' ? 0 : 1,
    }).format(value)
  } catch {
    // `style: 'unit'` is widely supported but not universal; fall back to a plain number.
    return new Intl.NumberFormat(locale, {
      maximumFractionDigits: unit === 'byte' ? 0 : 1,
    }).format(value)
  }
}

/** One word describing the list as a whole, for the live region. */
function statusSummary(
  files: UploaderFile[],
  uploading: string,
  complete: string,
  error: string,
): string {
  if (files.some((f) => f.status === 'error')) return error
  if (files.some((f) => f.status === 'uploading')) return uploading
  return complete
}

export function FileUploader({
  files = [],
  onFilesAdded,
  onRemove,
  multiple = false,
  accept,
  maxSize,
  onRejected,
  label,
  ariaLabel,
  hint,
  labels,
  disabled = false,
  className,
}: FileUploaderProps) {
  useSignals()
  const locale = currentLocale()
  const inputRef = useRef<HTMLInputElement>(null)
  const dragOver = useSignal(false)

  const resolvedLabel = label ?? labels?.label ?? t(builtin.fileUploader.label)
  const resolvedDrop = labels?.drop ?? t(builtin.fileUploader.drop)
  const resolvedUploading = labels?.uploading ?? t(builtin.fileUploader.uploading)
  const resolvedComplete = labels?.complete ?? t(builtin.fileUploader.complete)
  const resolvedError = labels?.error ?? t(builtin.fileUploader.error)
  const resolveRemove = (name: string) =>
    labels?.remove
      ? labels.remove.replaceAll('{name}', name)
      : t(builtin.fileUploader.remove, { name })

  // useId, not a slug of the label: the default label is the same string for every instance,
  // so two uploaders on one page emitted duplicate ids and aria-describedby resolved to
  // whichever came first. A non-ASCII label also produced ids containing arbitrary characters.
  const baseId = useId('cascivo-uploader')
  const labelId = `${baseId}-label`
  const hintId = `${baseId}-hint`
  const statusId = `${baseId}-status`

  const processFiles = (list: FileList | null) => {
    if (!list || list.length === 0) return
    const incoming = multiple ? Array.from(list) : Array.from(list).slice(0, 1)
    const accepted: File[] = []
    const typeRejected: File[] = []
    const sizeRejected: File[] = []
    for (const file of incoming) {
      if (accept && !matchesAccept(file, accept)) {
        typeRejected.push(file)
      } else if (maxSize !== undefined && file.size > maxSize) {
        sizeRejected.push(file)
      } else {
        accepted.push(file)
      }
    }
    if (typeRejected.length > 0) onRejected?.(typeRejected, 'type')
    if (sizeRejected.length > 0) onRejected?.(sizeRejected, 'size')
    if (accepted.length > 0) onFilesAdded?.(accepted)
  }

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    processFiles(e.target.files)
    e.target.value = ''
  }

  const handleDrop = (e: DragEvent<HTMLButtonElement>) => {
    e.preventDefault()
    dragOver.value = false
    if (disabled) return
    processFiles(e.dataTransfer.files)
  }

  return (
    <div className={cn(styles['uploader'], className)}>
      <span id={labelId} className={styles['label']}>
        {resolvedLabel}
      </span>
      <input
        ref={inputRef}
        type="file"
        className={styles['input']}
        tabIndex={-1}
        multiple={multiple}
        accept={accept}
        disabled={disabled}
        onChange={handleChange}
      />
      <button
        type="button"
        className={styles['zone']}
        data-state={dragOver.value ? 'dragover' : 'idle'}
        disabled={disabled}
        aria-labelledby={ariaLabel ? undefined : labelId}
        aria-label={ariaLabel}
        aria-describedby={hint ? hintId : undefined}
        onClick={() => inputRef.current?.click()}
        onDragEnter={(e) => {
          e.preventDefault()
          if (!disabled) dragOver.value = true
        }}
        onDragOver={(e) => {
          e.preventDefault()
          if (!disabled) e.dataTransfer.dropEffect = 'copy'
        }}
        onDragLeave={(e) => {
          // dragleave fires on the zone every time the pointer crosses onto a descendant, so
          // the unguarded version dropped the drag-over state mid-drag. `.zoneText` is
          // pointer-events: none for the browsers that report a null relatedTarget here.
          if (!e.currentTarget.contains(e.relatedTarget as Node)) dragOver.value = false
        }}
        onDrop={handleDrop}
      >
        <span className={styles['zoneText']}>{resolvedDrop}</span>
      </button>
      {hint && (
        <span id={hintId} className={styles['hint']}>
          {hint}
        </span>
      )}
      {/* Mounted unconditionally: a live region added in the same commit as its first
          content announces nothing, which is why the first upload was always silent. */}
      <span id={statusId} className={styles['srOnly']} role="status" aria-live="polite">
        {files.length > 0
          ? t(builtin.fileUploader.status, {
              count: files.length,
              state: statusSummary(files, resolvedUploading, resolvedComplete, resolvedError),
            })
          : ''}
      </span>
      {files.length > 0 && (
        <ul className={styles['list']}>
          {files.map((file) => (
            <li key={file.id} className={styles['file']} data-state={file.status}>
              <span className={styles['status']}>
                {file.status === 'uploading' && <Spinner size="sm" label={resolvedUploading} />}
                {file.status === 'complete' && (
                  <span className={styles['glyph-complete']} role="img" aria-label={resolvedComplete}>
                    ✓
                  </span>
                )}
                {file.status === 'error' && (
                  <span className={styles['glyph-error']} role="img" aria-label={resolvedError}>
                    ✕
                  </span>
                )}
              </span>
              <span className={styles['name']}>{file.name}</span>
              {file.size !== undefined && (
                <span className={styles['size']}>{formatSize(file.size, locale)}</span>
              )}
              <button
                type="button"
                className={styles['remove']}
                aria-label={resolveRemove(file.name)}
                disabled={disabled}
                onClick={() => onRemove?.(file.id)}
              >
                ✕
              </button>
              {file.status === 'error' && file.errorMessage && (
                <span className={styles['error-message']} role="alert">
                  {file.errorMessage}
                </span>
              )}
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

@layer cascivo.component {
  .uploader {
    /* A grid/flex item's default minimum is its content size, so a control with an
       intrinsic width (an <input> defaults to ~20ch) refuses to shrink and spills out of
       its track — reported as "Input overflows its grid cell" inside <Grid cols={{md:2}}>. */
    min-inline-size: 0;
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-2);
    inline-size: 100%;
  }

  .label {
    font-size: var(--cascivo-text-sm);
    font-weight: var(--cascivo-font-medium);
    color: var(--cascivo-color-text);
  }

  .input {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  .zone {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: var(--cascivo-space-8) var(--cascivo-space-4);
    border: 2px dashed var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-surface);
    background: var(--cascivo-color-surface);
    color: var(--cascivo-color-text-muted);
    font-size: var(--cascivo-text-sm);
    cursor: pointer;
    transition:
      border-color var(--cascivo-duration-150) var(--cascivo-ease-out),
      background var(--cascivo-duration-150) var(--cascivo-ease-out);
    inline-size: 100%;
    text-align: center;
  }

  .zone:hover:not(:disabled) {
    border-color: var(--cascivo-color-accent);
    background: var(--cascivo-color-accent-subtle);
  }

  .zone[data-state='dragover'] {
    border-color: var(--cascivo-color-accent);
    background: var(--cascivo-color-accent-subtle);
  }

  .zone:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }

  .hint {
    font-size: var(--cascivo-text-xs);
    color: var(--cascivo-color-text-muted);
  }

  .list {
    list-style: none;
    padding: 0;
    margin: 0;
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-2);
  }

  .file {
    display: grid;
    grid-template-columns: auto 1fr auto auto;
    grid-template-areas: 'status name size remove' 'status error error error';
    align-items: center;
    gap: var(--cascivo-space-2);
    padding: var(--cascivo-space-2) var(--cascivo-space-3);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-surface);
    background: var(--cascivo-color-surface);
    font-size: var(--cascivo-text-sm);
  }

  .file[data-state='error'] {
    border-color: var(--cascivo-color-destructive);
  }

  .status {
    grid-area: status;
    display: flex;
    align-items: center;
  }

  .glyph-complete {
    color: var(--cascivo-color-success-foreground);
  }

  .glyph-error {
    color: var(--cascivo-color-destructive);
  }

  .name {
    grid-area: name;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .size {
    grid-area: size;
    color: var(--cascivo-color-text-muted);
    font-size: var(--cascivo-text-xs);
  }

  .remove {
    grid-area: remove;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: var(--cascivo-space-1);
    border: none;
    border-radius: var(--cascivo-radius-control);
    background: transparent;
    color: var(--cascivo-color-text-muted);
    cursor: pointer;
    font-size: var(--cascivo-text-xs);
    line-height: 1;
  }

  .remove:hover {
    color: var(--cascivo-color-destructive);
    background: var(--cascivo-color-destructive-subtle);
  }

  .error-message {
    grid-area: error;
    font-size: var(--cascivo-text-xs);
    color: var(--cascivo-color-destructive);
  }

  /* Belt and braces with the `relatedTarget` guard in the handler: Safari reports a null
     `relatedTarget` on dragleave, so the JS check alone cannot tell "left for a child" from
     "left the zone". Making the text untargetable keeps the pointer on the button either way. */
  .zoneText {
    pointer-events: none;
  }

  .srOnly {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }

  /* The remove button was roughly 20px — below even WCAG 2.2 SC 2.5.8's 24px floor, let alone
     the repo's 44px coarse-pointer rule — and the file had no block at all. */
  @media (pointer: coarse) {
    .remove {
      min-inline-size: var(--cascivo-target-min-coarse, 2.75rem);
      min-block-size: var(--cascivo-target-min-coarse, 2.75rem);
    }
  }
}

@media (forced-colors: active) {
  /* Drag-over, disabled, error and success were each encoded only as colour, which
     forced-colors flattens away entirely. */
  .zone[data-state='dragover'] {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }

  .zone:disabled {
    color: GrayText;
  }

  .file[data-state='error'] .glyph-error,
  .error-message {
    color: CanvasText;
    forced-color-adjust: none;
  }

  .zone:focus-visible,
  .remove:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 1px;
  }
}
